-- Comprehensive NASA Data Quiz Setup for Harvestia
-- Single script to create all NASA-related quizzes and questions
-- Run this once in Supabase SQL Editor

-- Clean up existing NASA quizzes
delete from public.quiz_questions
 where quiz_id like 'nasa-%';
delete from public.quizzes
 where id like 'nasa-%';

-- Create NASA Data Quizzes
insert into public.quizzes (
   id,
   title,
   difficulty,
   nasa_topic,
   questions_count,
   attempts_allowed
) values ( 'nasa-basics',
           'NASA Satellite Data for Smart Farming',
           'Easy',
           'Satellite Data Basics',
           0,
           3 ),( 'nasa-practical',
                 'Practical NASA Data Applications',
                 'Medium',
                 'Farm Applications',
                 0,
                 3 ),( 'nasa-advanced',
                       'Advanced NASA Data Integration',
                       'Hard',
                       'Data Analysis',
                       0,
                       3 ),( 'nasa-seasonal',
                             'NASA Data for Seasonal Planning',
                             'Medium',
                             'Crop Planning',
                             0,
                             3 );

-- NASA Basics Quiz Questions (Easy Level)
insert into public.quiz_questions (
   quiz_id,
   question,
   options,
   correct_answer,
   explanation
) values ( 'nasa-basics',
           'Which NASA satellite provides soil moisture data for agriculture?',
           '["MODIS", "SMAP", "Landsat", "GOES"]',
           'SMAP',
           'SMAP (Soil Moisture Active Passive) specifically measures soil moisture from space, essential for irrigation planning and drought monitoring.'
           ),( 'nasa-basics',
                                                                                                                                                           'What does NDVI measure in satellite imagery?'
                                                                                                                                                           ,
                                                                                                                                                           '["Soil temperature", "Vegetation health and biomass", "Rainfall amount", "Wind speed"]'
                                                                                                                                                           ,
                                                                                                                                                           'Vegetation health and biomass'
                                                                                                                                                           ,
                                                                                                                                                           'NDVI (Normalized Difference Vegetation Index) indicates plant health, leaf density, and photosynthetic activity using near-infrared and red light.'
                                                                                                                                                           )
                                                                                                                                                           ,
                                                                                                                                                           (
                                                                                                                                                           'nasa-basics'
                                                                                                                                                           ,
                                                                                                                                                                                                                                                                                                                'Which NASA mission provides global precipitation data?'
                                                                                                                                                                                                                                                                                                                ,
                                                                                                                                                                                                                                                                                                                '["Solar radiation monitoring", "Global Precipitation Measurement (GPM)", "Soil pH measurement", "Pest population tracking"]'
                                                                                                                                                                                                                                                                                                                ,
                                                                                                                                                                                                                                                                                                                'Global Precipitation Measurement (GPM)'
                                                                                                                                                                                                                                                                                                                ,
                                                                                                                                                                                                                                                                                                                'GPM provides global precipitation measurements every 3 hours, crucial for rainfall monitoring and irrigation planning.'
                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                ,
                                                                                                                                                                                                                                                                                                                (
                                                                                                                                                                                                                                                                                                                'nasa-basics'
                                                                                                                                                                                                                                                                                                                ,
                                                                                                                                                                                                                                                                                                                                                                                                                                         'What weather parameters does NASA POWER provide for agriculture?'
                                                                                                                                                                                                                                                                                                                                                                                                                                         ,
                                                                                                                                                                                                                                                                                                                                                                                                                                         '["Only temperature", "Temperature, humidity, solar radiation, wind speed", "Only rainfall", "Only cloud cover"]'
