-- Update question counts
update public.quizzes
   set
   questions_count = (
      select count(*)
        from public.quiz_questions
       where quiz_id = quizzes.id
   )
 where id like 'nasa-%';

-- Verify setup
select 'NASA Quiz Setup Complete!' as status,
       (
          select count(*)
            from public.quizzes
           where id like 'nasa-%'
       ) as quizzes_created,
       (
          select count(*)
            from public.quiz_questions
           where quiz_id like 'nasa-%'
       ) as questions_created;